use vstd::prelude::*;

verus! {
    fn reverse(a: &[i32]) -> (result: Vec<i32>)
        ensures
            result.len() == a.len(),
            forall|i: nat| 0 <= i < a.len() ==> result[i] == a[(a.len() - 1 - i) as usize],
    {
        let n = a.len();
        let mut result: Vec<i32> = Vec::new();
        result.resize(n, 0); // Initialize the result vector with the same length as input

        let mut i: usize = 0;
        while i < n
            invariant
                i <= n,
                forall|j: nat| 0 <= j < i ==> result[j] == a[(n - 1 - j) as usize],
            decreases n - i,
        {
            result[i] = a[(n - 1 - i) as usize]; // Fill the result vector in reverse order
            i = i + 1;
        }
        result
    }
}
